// Pseudocode for Space-Saving with K counters
class Counter { constructor(id, count) { this.id = id; this.count = count; } }
let counters = new Map();
function update(e){
  if (counters.has(e)) { counters.get(e).count++ }
  else {
    if (counters.size < K) { counters.set(e, {count:1}) } 
    else { // replace min
      let minEntry = null; let minCount = Infinity;
      for (let [id, c] of counters) { if (c.count < minCount) { minCount = c.count; minEntry = id; } }
      counters.delete(minEntry);
      counters.set(e, {count: minCount + 1});
    }
  }
}
```

